#[verifier::spec]
fn is_power_of_two_u8(u: u8) -> bool {
    // standard bit‐trick: exactly one bit set
    u > 0 && (u & (u - 1)) == 0
}

#[verifier::spec]
fn is_ashish(n: i8) -> bool {
    if n == 1 {
        false
    } else if n == 2 {
        true
    } else {
        let u: u8 = n as u8;
        if is_power_of_two_u8(u) {
            // any power‐of‐two > 2
            false
        } else if n % 4 != 2 {
            // all odds and multiples of 4 (except 2)
            true
        } else {
            // n % 4 == 2 and n > 2
            let p = n / 2;
            // limited‐prime test:
            //   p > 1  and  (p == 2 or p is odd)
            !(p > 1 && (p == 2 || p % 2 != 0))
        }
    }
}

