#[verifier::verus]
#[requires(input.len() >= 1 + (input[0] as usize))]
#[ensures(result.len() == input[0] as usize)]
#[ensures(
    forall(|i: usize| i < result.len() ==>
        let n = input[1 + i];
        if  is_ashish(n) { result[i] == "Ashishgup" }
        else             { result[i] == "FastestFinger" }
    )
)]
fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // We must have at least one element (the count t),
    // and at least t more elements to process.
    let mut iter = input.into_iter();
    let t = iter.next().expect("input must contain at least one element") as usize;
    let mut result = Vec::with_capacity(t);

    for n in iter.take(t) {
        // We'll produce one of these two strings for each test case.
        const FAST: &str = "FastestFinger";
        const ASHI: &str = "Ashishgup";

        let winner = if n == 1 {
            FAST
        } else if n == 2 {
            ASHI
        } else {
            // Cast to u8 for an easy power‐of‐two check.
            let u = n as u8;
            if u.is_power_of_two() {
                // Any power of two > 2 => FastestFinger
                FAST
            } else if n % 4 != 2 {
                // All odds and multiples of 4 (except 2) => Ashishgup
                ASHI
            } else {
                // n % 4 == 2 and n > 2 => let p = n/2
                let p = n / 2;
                // limited‐prime: p <= 1 => not prime;
                // p == 2 => prime;
                // odd p > 2 => prime;
                // even p > 2 => not prime
                let is_limited_prime = p > 1 && (p == 2 || p % 2 != 0);
                if is_limited_prime {
                    FAST
                } else {
                    ASHI
                }
            }
        };

        // show that the implemented branch matches our spec for "Ashish" vs "Fastest"
        assert!(winner
            == if is_ashish(n) { ASHI } else { FAST });

        result.push(winner);
    }

    // exactly t pushes => length == t
    assert!(result.len() == t);

    result
}

